    42→            }
    43→
    44→            AddTransitions(transitionBlockNumbers, _chainSpec, static n => n.EndsWith("BlockNumber") && n != "TerminalPoWBlockNumber");
    45→            AddTransitions(transitionBlockNumbers, _chainSpec.Parameters, static n => n.EndsWith("Transition"));
    46→            AddTransitions(transitionTimestamps, _chainSpec.Parameters, static n => n.EndsWith("TransitionTimestamp"), _chainSpec.Genesis?.Timestamp ?? 0);
    47→            AddBlobScheduleTransitions(transitionTimestamps, _chainSpec);
    48→            TimestampFork = transitionTimestamps.Count > 0 ? transitionTimestamps.Min : ISpecProvider.TimestampForkNever;
    49→
    50→            static void AddTransitions<T>(
    51→                SortedSet<T> transitions,
    52→                object value,
    53→                Func<string, bool> matchPropertyName, T? minValueExclusive = null)
    54→                where T : struct, INumber<T>
    55→            {
    56→                static void Add(SortedSet<T> transitions, T value, T? minValueExclusive)
    57→                {
